<template>
  <div class="demo-wrapper">
    <div class="container" ref="containerRef"></div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'

const containerRef = ref(null)

const LENGTH = 50
const DISTANCE = 1
const STR = ''

const init = () => {
  if (!containerRef.value) return

  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
  svg.setAttribute('viewBox', `0 0 ${LENGTH * 3} ${LENGTH * 2}`)

  const polygon = document.createElementNS('http://www.w3.org/2000/svg', 'polygon')
  let points = ''
  let y = 0

  for (let i = 0; i < LENGTH; i++) {
    y += DISTANCE
    if (i % 2 === 1) points += ` 0,${y} ${LENGTH},${y}`
    else points += ` ${LENGTH},${y} 0,${y}`
  }

  points += ` ${LENGTH},${y} ${LENGTH * 2},${y}`

  for (let i = 0; i < LENGTH; i++) {
    if (i % 2 === 0) points += `  ${LENGTH * 2},${y}  ${LENGTH * 3},${y}`
    else points += `  ${LENGTH * 3},${y}  ${LENGTH * 2},${y}`
    y += DISTANCE
  }

  polygon.setAttribute('points', points)
  svg.appendChild(polygon)
  containerRef.value.appendChild(svg)

  setDasharray(polygon)
  setInitialOffset(polygon)
}

const setDasharray = (polygon) => {
  const strData = STR.split('')
  let strArray = []
  strData.forEach((nums, i) => {
    const index = Math.floor(i / LENGTH)
    if (!strArray[index]) strArray[index] = []
    strArray[index].push(nums)
  })

  let dasharray = '0'
  strArray.forEach((array, index) => {
    let arr = index % 2 === 1 ? array : [...array].reverse()
    arr.forEach((nums) => {
      if (parseInt(nums)) dasharray += ' 1 0'
      else dasharray += ' 0 1'
    })
    dasharray += ` ${DISTANCE} 0`
  })
  dasharray += ' 10000 0 10000'
  polygon.style.strokeDasharray = dasharray
}

const setInitialOffset = (polygon) => {
  polygon.style.strokeDashoffset = '0'
}

const toggleOffset = () => {
  const polygon = containerRef.value?.querySelector('polygon')
  if (!polygon) return
  const current = parseFloat(polygon.style.strokeDashoffset) || 0
  const target = current === 0
    ? -(LENGTH * LENGTH + DISTANCE * LENGTH + LENGTH - DISTANCE)
    : 0
  polygon.style.strokeDashoffset = `${target}`
}

onMounted(() => {
  init()
  window.addEventListener('click', toggleOffset)
})
</script>

<style scoped>
* {
  font-size: 2vmin;
  padding: 0;
  margin: 0;
}

.demo-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100vw;
  height: 100vh;
  background-color: #171717;
}

.container {
  position: absolute;
}

svg {
  height: 40rem;
  overflow: visible;
}

svg polygon {
  fill: none;
  stroke-width: 2;
  stroke: #17f700;
  transition: stroke-dashoffset 0.3s ease;
}
</style>
